
with filter0_sjd as (
    -- claims
    select ptid,
           trim(upper(replace(diag,'.',''))) as diagnosis_cd,
           fst_dt as event_date
    from market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_clm_med_diag
    where fst_dt >= cast('2021-10-01' as date)
      and fst_dt <= cast('2026-03-31' as date)
      and trim(upper(replace(diag,'.',''))) like 'M350%'
    union all
    -- EHR
    select ptid,
           trim(upper(replace(diagnosis_cd,'.',''))) as diagnosis_cd,
           diag_date as event_date
    from market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_diag
    where diag_date >= cast('2021-10-01' as date)
      and diag_date <= cast('2026-03-31' as date)
      and trim(upper(replace(diagnosis_cd,'.',''))) like 'M350%'
),

deceased_patients as (
    select ptid,
try(cast(date_parse(trim(cast(date_of_death as varchar)) || '01', '%Y%m%d') as date)) as dod_eom
    from market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_pt
    where deceased_indicator = '1'
      and date_of_death is null
),

-- patients in our SjD cohort who died and still have diagnosis activity after death

deceased_with_post_death_activity as (
    select distinct d.ptid
    from (
        -- deceased patients (in filter0_sjd cohort) with a parseable death month -> end of month
        select f.ptid,
               last_day_of_month(
                   try(cast(date_parse(trim(cast(p.date_of_death as varchar)) || '01', '%Y%m%d') as date))
               ) as dod_eom
        from (select distinct ptid from filter0_sjd) f
        join market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_pt p
          on f.ptid = p.ptid
        where p.deceased_indicator = '1'
           or p.date_of_death is not null
    ) d
    join (
        -- ANY diagnosis activity, full tables, no date window
        select ptid, cast(fst_dt   as date) as event_date
        from market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_clm_med_diag
        union all
        select ptid, cast(diag_date as date) as event_date
        from market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_diag
    ) act
      on d.ptid = act.ptid
    where d.dod_eom is not null            -- unparseable/unknown death date -> can't flag
      and act.event_date > d.dod_eom       -- activity strictly after the death month
),


filter1_sjd as (
    select *
    from filter0_sjd
    where ptid not in (select ptid from excluded_patients_2026)
      and ptid not in (select ptid from deceased_patients)
      and ptid not in (select ptid from deceased_with_post_death_activity)
),

sjd_dates as (
    select distinct ptid, event_date
    from filter1_sjd
),

-- STEP 1: age at EVERY event date

age_all_dates as (
   
    select * from (
    select *, case when age >= 18 then 1 else 0 end as is_adult from (
    select *, year(event_date) - final_birth_yr as age
    from (
        select a.*,
               case when b.birth_yr = '1937 and Earlier' then 1937
               when b.birth_yr = '1936 and Earlier' then 1936
                    when b.birth_yr = 'Unknown' then null
                    else try_cast(b.birth_yr as int)
               end as final_birth_yr
        from sjd_dates a
        left join market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_pt b
          on a.ptid = b.ptid
    ))

)

where is_adult = 1

),

sjd_pairs as (
    select earlier.*,
           earlier.event_date as earlier_date,
           later.event_date as later_date,
           date_diff('day', earlier.event_date, later.event_date) as days_apart
    from age_all_dates earlier
    inner join age_all_dates later
      on earlier.ptid = later.ptid and earlier.event_date < later.event_date
     and date_diff('day', earlier.event_date, later.event_date) between 30 and 365
),

---- recitification needed for cont enrollment:
-- death date is YYYYMM -> first of month (matches pt_master.dod in the screenshots)
death_info as (
    select ptid,
           try(cast(date_parse(trim(cast(date_of_death as varchar)) || '01', '%Y%m%d') as date)) as dod
    from market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_pt
    where deceased_indicator = '1' and date_of_death is not null
),

enroll_spans as (
    select distinct trim(upper(e.ptid)) as ptid,
           cast(e.eligeff as date) as eligeff,
           least(
               cast(e.eligend as date),
               coalesce(di.dod, date '2026-03-31'),   -- cap at death
               date '2026-03-31'                       -- cap at data cutoff
           ) as eligend_mod
    from market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_clm_con_enrl e
    left join death_info di
      on trim(upper(e.ptid)) = trim(upper(di.ptid))
    where e.coverage_ind in ('Med+Rx')
),

enrollment_flag as (
    select d.ptid,
           d.event_date,
           max(case when e.eligeff     <= date_add('day', -365, d.event_date)
                     and e.eligend_mod >= date_add('day',  365, d.event_date)
                    then 1 else 0 end) as is_cont_enrolled
    from sjd_dates d
    left join enroll_spans e
      on trim(upper(d.ptid)) = trim(upper(e.ptid))
    group by d.ptid, d.event_date
),

-- index candidates = earlier date of a qualifying pair (already adult + paired)
-- that is ALSO continuously enrolled at that date
qualified_index_dates as (
    select distinct p.ptid, p.earlier_date
    from sjd_pairs p
    join enrollment_flag ef
      on p.ptid = ef.ptid
     and p.earlier_date = ef.event_date
    where ef.is_cont_enrolled = 1
),

-- index = earliest date satisfying adult + has_pair + is_cont_enrolled
index_define as (
    select ptid,
           min(earlier_date) as date_of_first_diagnosis
    from qualified_index_dates
    group by ptid
)

--- join for elig end and elig eff

select a.* ,b.eligeff, b.eligend_mod from final_cohort_2026 a
left join enroll_spans b on a.ptid = b.ptid and date_of_first_diagnosis	
between eligeff and eligend_mod
order by 1





--- baseline START
with baseline_demographics as (
    select a.*, b.birth_yr, b.gender, b.race, b.ethnicity, b.region
    from final_cohort_2026 a
    left join market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_pt b
      on a.ptid = b.ptid
),


birth_year_normalized as (
    select *,
           case when birth_yr = '1937 and Earlier' then '1937'
                when birth_yr = 'Unknown'          then null
                else birth_yr
           end as final_birth_yr
    from baseline_demographics
),

birth_date_corrected as (
    select ptid, date_of_first_diagnosis,
           try(cast(date_parse(concat(final_birth_yr, '0101'), '%Y%m%d') as date)) as birth_yr_latest,
           gender, race, ethnicity, region
    from birth_year_normalized
),

-- Age at index
baseline_with_age as (
    select ptid, date_of_first_diagnosis, gender, race, ethnicity, region,
           date_diff('year', birth_yr_latest, date_of_first_diagnosis) as age_index
    from birth_date_corrected
),

-- All diagnoses 
all_diagnoses as (
    select distinct ptid, cast(fst_dt as date) as claim_date,
           trim(upper(replace(diag,'.',''))) as dx
    from market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_clm_med_diag
    where ptid in (select distinct ptid from final_cohort_2026)
    union
    select distinct ptid, cast(diag_date as date) as claim_date,
           trim(upper(replace(diagnosis_cd,'.',''))) as dx
    from market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_diag
    where ptid in (select distinct ptid from final_cohort_2026)
),

-- index date attach each diagnosis
diagnoses_with_index as (
    select a.*, b.date_of_first_diagnosis
    from all_diagnoses a
    inner join final_cohort_2026 b on a.ptid = b.ptid
),

-- cci index

cci_scores_with_rheum as (
    select ptid,
           ( max(hiv_score) + max(AnyM_score) + max(cvd_score) + max(cpd_score) + max(chf_score)
           + max(dementia_score) + max(DwCC_score) + max(DwoCC_score) + max(Hemi_Para_score)
           + max(MetaST_score) + max(MLD_score) + max(MSLiverD_score) + max(MI_score)
           + max(PUD_score) + max(PVD_score) + max(RenalD_score)) as CCI
