        from diagnoses_with_index
        where claim_date <  date_of_first_diagnosis
          and claim_date >= date_add('day', -365, date_of_first_diagnosis)
    )
    group by ptid
),

-- Insurance spans covering the index date
insurance_spans as (
    select a.*, b.eligeff, b.eligend, b.bus
    from baseline_with_age a
    left join market_clarity_graves_disease_202605_v1_20260622_prod.argenx_graves_202605_clm_mbr_dtl b
      on a.ptid = b.ptid
     and a.date_of_first_diagnosis between b.eligeff and coalesce(b.eligend, cast('2099-01-01' as date))
),

-- priority rank
insurance_priority_mapped as (
    select *,
           case when bus = 'COM' then 1
                when bus = 'MCR' then 2
                when bus = 'MCD' then 3
                when bus = 'UNK' then 4
                else 0
           end as mapped
    from insurance_spans
),

-- Rank ins type within each patient
insurance_ranked as (
    select *,
           row_number() over (partition by ptid order by mapped) as priority_order
    from insurance_priority_mapped
),

-- only highest-priority payer per patient
primary_insurance as (
    select * from insurance_ranked where priority_order = 1
)

-- Final baseline table (demographics + age + insurance + CCI)

select p.*, coalesce(c.CCI, 0) as CCI_without_rheum
from primary_insurance p
left join cci_scores_with_rheum c on p.ptid = c.ptid
order by 1




